import { assignmentStatusItems } from '~/constants/assignments/assignmentStatusConfig';
import type { AssignmentStatus } from '~/client';

export function filteredAssignmentStatusesForTabs(): SelectItem<AssignmentStatus | 'all'>[] {
  const filteredStatuses = assignmentStatusItems.filter(
    (item) =>
      item.value !== 'training_scheduled' && item.value !== 'no_call_no_show' && item.value !== 'project_completed'
  );
  return [{ name: 'All', value: 'all' }, ...filteredStatuses];
}
