import { assignUserToProject, type UserAssignProjectData } from '~/client';

export const useAssignUserToProject = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync: assignUser, asyncStatus } = useMutation({
    mutation: (params: {
      user_id: string;
      data: UserAssignProjectData;
      assignmentsCacheParams: AssignmentCacheParams;
    }) =>
      assignUserToProject({
        composable: '$fetch',
        path: { user_id: params.user_id },
        body: ref(params.data),
      }),
    onSuccess: (_, { user_id, data, assignmentsCacheParams }) => {
      if (assignmentsCacheParams.scope === 'project') {
        queryCache.invalidateQueries({ key: ['project-assignments', data.project_id, assignmentsCacheParams.params] });
        queryCache.invalidateQueries({ key: ['selector-unassigned-users', data.project_id] });
      } else {
        queryCache.invalidateQueries({ key: ['user-assignments', user_id, assignmentsCacheParams.params] });
        queryCache.invalidateQueries({ key: ['selector-unassigned-projects', user_id] });
      }
      showToastSuccess('User assigned successfully');
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    assignUser,
    isAssigningUser: computed(() => asyncStatus.value === 'loading'),
  };
});
