import { toTypedSchema } from '@vee-validate/zod';
import { useForm } from 'vee-validate';
import type {
  CanvassingProjectPricing,
  CanvassingSelectorPricing,
  ProjectType,
  SignatureProjectPricing,
  SignatureSelectorPricing,
  UserRole,
} from '~/client';
import { buildAssignmentInfoSchema, type AssignmentInfoFormOutput } from '~/constants/validationSchemas/assignmentInfo';
import { defaultPositionForRole } from '~/constants/assignments/positionDefaults';

export type AssignmentPayment =
  | SignatureSelectorPricing
  | CanvassingSelectorPricing
  | SignatureProjectPricing
  | CanvassingProjectPricing;

interface UseCanvasserAssignmentFormOptions {
  projectType: MaybeRefOrGetter<ProjectType>;
  payment: MaybeRefOrGetter<AssignmentPayment>;
  isRegularCanvasser: MaybeRefOrGetter<boolean>;
  projectId: MaybeRefOrGetter<string>;
  userId: MaybeRefOrGetter<string | null | undefined>;
  /** Target user's role — drives the prefilled default position. */
  userRole: MaybeRefOrGetter<UserRole | undefined>;
  assignmentsCacheParams: MaybeRefOrGetter<AssignmentCacheParams>;
  onAssigned: () => void;
}

export function useCanvasserAssignmentForm(options: UseCanvasserAssignmentFormOptions) {
  const { assignUser, isAssigningUser } = useAssignUserToProject();

  const projectType = computed(() => toValue(options.projectType));
  const payment = computed(() => toValue(options.payment));
  const isRegularCanvasser = computed(() => toValue(options.isRegularCanvasser));
  const increasedPayRateEnabled = computed(() => isIncreasedPayRateApplicable(payment.value));
  const defaultPosition = computed(() => defaultPositionForRole(toValue(options.userRole)) || null);
  const isCanvasserLike = computed(() => {
    const role = toValue(options.userRole);
    return role === 'canvasser' || role === 'subcontractor_canvasser';
  });

  const schema = computed(() =>
    toTypedSchema(
      buildAssignmentInfoSchema({
        projectType: projectType.value,
        paymentEnabled: payment.value.payments_enabled,
        increasedPayRateEnabled: increasedPayRateEnabled.value,
        payRateApplicable: isRegularCanvasser.value,
        canvassingAppUsernameApplicable: isCanvasserLike.value,
        mode: 'create',
      })
    )
  );

  const { handleSubmit, setValues, resetForm } = useForm({
    validationSchema: schema,
  });

  function applyDefaults() {
    if (isRegularCanvasser.value) {
      setValues(
        {
          assignment_type: 'local',
          rate: null,
          increased_price_per_hour: null,
          canvasser_in_app: null,
          position: defaultPosition.value,
        },
        false
      );
    } else {
      setValues({ canvasser_in_app: null, position: defaultPosition.value }, false);
    }
  }

  const submitAssignment = handleSubmit(async (values: AssignmentInfoFormOutput) => {
    const userId = toValue(options.userId);
    if (!userId) return;

    const isCanvassing = projectType.value === 'canvassing';
    const isSignature = projectType.value === 'signature';

    await assignUser({
      user_id: userId,
      data: {
        project_id: toValue(options.projectId),
        price_per_signature: isRegularCanvasser.value && isSignature ? (values.rate ?? null) : null,
        price_per_hour: isRegularCanvasser.value && isCanvassing ? (values.rate ?? null) : null,
        canvassing_application_user_email: isCanvassing ? (values.canvasser_in_app ?? null) : null,
        assignment_type: isRegularCanvasser.value ? (values.assignment_type ?? null) : null,
        increased_price_per_hour:
          isRegularCanvasser.value && isCanvassing ? (values.increased_price_per_hour ?? null) : null,
        position: values.position ?? null,
      },
      assignmentsCacheParams: toValue(options.assignmentsCacheParams),
    });

    options.onAssigned();
  });

  return {
    schema,
    setValues,
    resetForm,
    applyDefaults,
    submitAssignment,
    isAssigningUser,
  };
}
